cd /tmp/claude-1000/-home-scottdensmore-Developer-scottdensmore-super-star-trek/8bd691e1-6038-4f0d-82d9-378514dcc470/scratchpad
cat > wprobe.c <<'EOF'
#include <stdio.h>
int probe(int n) {
	int v;
	if (n > 0) v = n * 2;
	return v;          /* only reachable-uninitialised under optimisation */
}
int main(void) { printf("%d\n", probe(1)); return 0; }
EOF
W="-Wall -Wextra -Wmissing-prototypes"
echo "=== Debug flags (-g, no optimisation) ==="
gcc $W -g -std=gnu17 -c wprobe.c -o /dev/null 2>&1 | grep -c 'warning:' | xargs echo "warnings:"
echo "=== Release flags (-O3 -DNDEBUG) ==="
gcc $W -O3 -DNDEBUG -std=gnu17 -c wprobe.c -o /dev/null 2>&1 | tee w.txt | grep -c 'warning:' | xargs echo "warnings:"
grep 'warning:' w.txt | head -2
echo "=== and with -Werror, as ci-release has it ==="
gcc $W -O3 -DNDEBUG -Werror -std=gnu17 -c wprobe.c -o /dev/null >/dev/null 2>&1; echo "ci-release exit: $?"
gcc $W -g -Werror -std=gnu17 -c wprobe.c -o /dev/null >/dev/null 2>&1; echo "ci-debug   exit: $?"
rm -f wprobe.c w.txt

